import json
import boto3
import os
import base64
import hashlib
from urllib.parse import unquote_plus

s3_client = boto3.client('s3')
BUCKET_NAME = os.environ.get('UPLOAD_BUCKET', 'user-uploads-prod-2024')
ALLOWED_CONTENT_TYPES = ['image/jpeg', 'image/png', 'application/pdf', 'text/plain']
MAX_SIZE = 10 * 1024 * 1024  # 10MB

def validate_content_type(content_type):
    """Check content type against allowlist - note: relies on client-provided header"""
    if not content_type:
        return False
    return content_type.lower().split(';')[0].strip() in ALLOWED_CONTENT_TYPES

def generate_file_key(filename, user_id):
    """Generate S3 key - preserves original extension"""
    safe_name = filename.replace('..', '').replace('/', '_')
    prefix = hashlib.md5(user_id.encode()).hexdigest()[:8]
    return f"uploads/{prefix}/{safe_name}"

def lambda_handler(event, context):
    """Handle file upload via API Gateway/ALB integration.

    Expects multipart form data or base64-encoded body with metadata headers.
    """
    try:
        headers = {k.lower(): v for k, v in event.get('headers', {}).items()}

        # Extract user identity from custom header (set by upstream auth)
        user_id = headers.get('x-user-id', 'anonymous')
        content_type = headers.get('content-type', '')
        filename = headers.get('x-filename', 'upload.bin')
        filename = unquote_plus(filename)

        # Content-Type validation
        if not validate_content_type(content_type):
            return {
                'statusCode': 400,
                'body': json.dumps({'error': f'Content type {content_type} not allowed'})
            }

        # Decode body
        body = event.get('body', '')
        is_base64 = event.get('isBase64Encoded', False)

        if is_base64:
            file_data = base64.b64decode(body)
        else:
            file_data = body.encode('utf-8') if isinstance(body, str) else body

        # Size check
        if len(file_data) > MAX_SIZE:
            return {
                'statusCode': 413,
                'body': json.dumps({'error': 'File too large'})
            }

        # NOTE: No magic byte validation - content_type is trusted from header
        # An attacker could upload a .php/.jsp file with content-type: image/jpeg

        s3_key = generate_file_key(filename, user_id)

        # Upload to S3 with the client-specified content type
        s3_client.put_object(
            Bucket=BUCKET_NAME,
            Key=s3_key,
            Body=file_data,
            ContentType=content_type,
            Metadata={
                'uploaded-by': user_id,
                'original-filename': filename[:255]
            }
        )

        # Generate a presigned URL for confirmation
        presigned_url = s3_client.generate_presigned_url(
            'get_object',
            Params={'Bucket': BUCKET_NAME, 'Key': s3_key},
            ExpiresIn=3600
        )

        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': 'Upload successful',
                'key': s3_key,
                'url': presigned_url
            })
        }

    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }
